import{_ as o,l as t,o as n,c as s,v as e,p as l,x as r,d as p,i as E,S as B}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Brinson 归因","description":"","frontmatter":{"title":"Brinson 归因","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/brinson.md","filePath":"quant/brinson.md","lastUpdated":1789023840000}'),h={name:"quant/brinson.md"};function _(d,a,m,A,u,c){const i=t("Mermaid");return n(),s("div",null,[a[1]||(a[1]=e('<h1 id="brinson-归因" tabindex="-1">Brinson 归因 <a class="header-anchor" href="#brinson-归因" aria-label="Permalink to &quot;Brinson 归因&quot;">​</a></h1><div class="epigraph"><p>组合相对基准的超额，可以拆成配置——在哪些大类上超低配——与选择——在大类内部选了什么；两者的交叉项是交互效应。</p><footer>—— Brinson, Hood and Beebower, Determinants of Portfolio Performance, Financial Analysts Journal, 1986</footer></div><p>绩效归因要回答的不是「今年赚了多少」，而是超额相对于基准来自哪一类主动决策。Brinson、Hood 与 Beebower（1986）给出一套至今仍是资产配置报告骨架的算术分解：把权重差乘以基准收益叫配置，把基准权重乘以内部超额叫选择，把两边的交叉叫交互。它依赖一套事先写好的资产类或行业分类，以及每个格子里可观测的组合收益与基准收益。相对后文的<a href="/quant/factor-attribution">因子归因</a>，Brinson 是持仓的分区会计，不是对风格因子收益的回归；相对 <a href="/quant/fundamental-risk-model">Barra 风险模型</a>，它不需要载荷与因子协方差，只需要对账。本篇写分解的代数、Brinson–Fachler 修正、多期连接，以及它解释不了什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记基准在类别 \\(i\\) 上的权重与收益为 \\(w_{b,i},R_{b,i}\\)，组合为 \\(w_{p,i},R_{p,i}\\)。总超额</p> \\[R_p-R_b=\\sum_i w_{p,i}R_{p,i}-\\sum_i w_{b,i}R_{b,i}. \\]<p>若不拆开，超配一个当时大涨的行业、与在行业内选到了更好的股票，会混在同一个数里。投委会无法判断该奖励行业观点还是选股过程，也无法判断跟踪误差来自<a href="/quant/portfolio-constraints">行业约束</a>没钉住还是来自内部名次。问题是给出一套可加的会计：每一项对应一种可命名的决策，加总还原超额，且不依赖收益的因子模型。</p><p>BHB 的样本结论——政策配置解释了计划收益变动的大部分——常被误读成「主动管理无用」。原文比较的是<strong>收益时间序列的方差来源</strong>（政策相对现金或相对市场的那一截），不是每一期超额的经济意义，更不是「配置 alpha 大于选股 alpha」。归因公式可以在单期上精确成立，而不支持那种跨期方差叙事。阅读时要把会计恒等式与 1986 年那张著名的百分比表分开。</p><h3 id="格子必须先于收益" tabindex="-1">格子必须先于收益 <a class="header-anchor" href="#格子必须先于收益" aria-label="Permalink to &quot;格子必须先于收益&quot;">​</a></h3><p>类别 \\(i\\) 是分区：行业、国家、资产类，必须在期初已知，权重必须是期初（或持有期开始时）的可投资权重。用期末权重乘本期收益，是把本期内价格变动造成的漂移算进配置，等于把<a href="/quant/rebalance-rules">再平衡</a>的缺失当成一种观点。分类还要与基准编制一致：组合用申万、基准用中证，交叉项会变成分类噪声。现金、衍生品、未分类股票必须有显式格子，否则残差不是「选择」，只是未分配。</p><p><span class="marginnote">Brinson 归因是对已经发生的持仓做的事后分解，不是一个预期收益模型。配置项为正，不表示行业观点有预测力；它只表示你超配了本期涨得多的基准格子。要把配置当成技能，需要跨期看该项的均值与跟踪误差，并承认样本很短。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>单期 BHB 分解写为三项：</p> \\[\\begin{aligned} \\mathrm{Alloc}&amp;=\\sum_i(w_{p,i}-w_{b,i})R_{b,i},\\\\ \\mathrm{Selec}&amp;=\\sum_i w_{b,i}(R_{p,i}-R_{b,i}),\\\\ \\mathrm{Inter}&amp;=\\sum_i(w_{p,i}-w_{b,i})(R_{p,i}-R_{b,i}). \\end{aligned} \\]<p>三者之和等于 \\(R_p-R_b\\)。配置用的是基准格子收益：你在「格子本身」上下注。选择用的是基准权重：即使你没有超配，内部超额仍按基准规模计入。交互是超配与内部超额的乘积——超配且选得好，交互为正；超配但选得差，交互为负。</p><p>Brinson 与 Fachler（1985）把配置改成相对总基准：</p> \\[\\mathrm{Alloc}^{\\mathrm{BF}}=\\sum_i(w_{p,i}-w_{b,i})(R_{b,i}-R_b). \\]<p>这样，超配一个跑输总基准的行业会记负配置，即使该行业收益为正。BHB 原式在所有行业都上涨时，超配权重大的行业容易「看起来像配置贡献」，BF 修正更符合「相对基准的行业观点」。实务报告应声明用的是哪一种；混用不可加总核对。</p><h3 id="多期连接不是把单期三项加起来" tabindex="-1">多期连接不是把单期三项加起来 <a class="header-anchor" href="#多期连接不是把单期三项加起来" aria-label="Permalink to &quot;多期连接不是把单期三项加起来&quot;">​</a></h3><p>单期算术超额不能直接相加得到多期超额，因为权重与基准都在复利。Carino（1999）与 Menchero（2000s）给出把单期效应连成多期、并保持可加性的算法：引入与组合和基准收益有关的连接因子，把各期配置、选择、交互按比例缩放后再加。几何归因则在对数空间里分解，解释更接近复利，但对投委会更不直观。无论哪条路，不要把十二个月的 BHB 三项直接求和当成年度超额——会计会裂开，残差会被误叫成「无法解释的 alpha」。</p><p>权重应使用与绩效计算相同的记账：交易发生在日中时，用日初权重会把当天交易的贡献挤进选择或交互。更干净的做法是日频归因再连接，而不是月频用月平均权重。平均权重会平滑掉你本来想看见的、由<a href="/quant/rebalance-rules">再平衡规则</a>造成的路径。</p><p><span class="marginnote">交互项常被报告成「残差」并忽略。它不是误差：大主动行业偏离乘上大内部超额时，交互可以主导单期。若章程要求行业中性，交互应接近零；若交互很大，说明行业约束在实现持仓上并没有生效。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分解能成立，是因为总收益是权重与格子收益的双线性形式。差分展开自然出现「权重差 × 基准收益」「基准权重 × 收益差」和交叉。它不需要假设收益由因子生成，也不需要假设主动权重最优。机制上，Brinson 度量的是<strong>决策的会计贡献</strong>，不是决策的质量期望。同一套超配，在行业大涨的月份贡献为正，在下月可对称为负。</p><p>选择项把格子内部的主动权重对格子基准的偏离折进 \\(R_{p,i}-R_{b,i}\\)。若格子太粗（一级行业），选择里仍含次行业配置；若格子太细，许多格子只有一两只股票，选择变成特异收益，统计上不可复述。这与<a href="/quant/industry-neutral">行业中性</a>的粗细权衡是同一问题：归因的分辨率不能细过你真正做过的决策层。</p><h3 id="与因子归因的分工" tabindex="-1">与因子归因的分工 <a class="header-anchor" href="#与因子归因的分工" aria-label="Permalink to &quot;与因子归因的分工&quot;">​</a></h3><p>因子归因把超额写成暴露差乘因子收益加残差，风格与行业可以同时出现，且不要求把股票分区到互斥格子。Brinson 要求互斥、穷尽的分类。一个价值超配可能在 Brinson 里表现为超配银行与周期，在因子归因里表现为价值与杠杆暴露。两套数字对不上不是 bug：它们回答不同的问题。工程上应让 Brinson 的行业分类与风险模型行业因子对齐，以便「行业配置项」能和风险报告里的行业贡献互相核对；风格则留给因子归因，不要在 Brinson 里再发明一个「价值格子」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>BHB 不处理择时的路径：月初超配、月中砍掉，月频归因看不见。它也不处理货币、对冲、杠杆衍生品：期货的名义暴露若不算进 \\(w_p\\)，配置项会漏掉最主要的主动决策。多空组合的权重可负，公式仍可写，但「超配」的语义要改成主动暴露，并单独报告总杠杆。</p><p>不要用 1986 年「配置解释 90% 以上方差」那句话来否定选股。那是计划资产相对其政策基准的方差分解，政策本身通常接近市场；主动超额的方差可以几乎全部来自选择，同时相对总资产仍很小。也不要把单期配置项的 t 统计量当行业择时技能：项数等于行业数，多重比较直接套 <a href="/quant/multiple-testing-factors">因子多重检验</a> 的逻辑。</p><p>现金与「未分类」若被塞进选择，选股权会虚高。衍生品与基金中基金要先映射到格子再归因，否则交互项会变成垃圾场。A 股停牌、涨跌停使部分权重不可调，实现 \\(w_p\\) 偏离意图 \\(w^{\\star}\\)；归因应能分开「意图配置」与「实施缺口」，否则把涨跌停造成的被动超配记成行业观点。</p><p><span class="marginnote">几何归因与算术归因对同一段样本可以给出不同的配置/选择份额。投委会若习惯看算术超额，就用带连接因子的算术多期；不要同一份季报里混用两套，再把差额叫做「模型误差」。</span></p>',32)),(n(),l(B,null,{default:r(()=>[E(i,{id:"mermaid-88",class:"mermaid",graph:"flowchart%20TD%0A%20%20WP%5B%22%E7%BB%84%E5%90%88%E6%9D%83%E9%87%8D%E4%B8%8E%E6%A0%BC%E5%AD%90%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20EX%5B%22%E8%B6%85%E9%A2%9D%20Rp%20-%20Rb%22%5D%0A%20%20WB%5B%22%E5%9F%BA%E5%87%86%E6%9D%83%E9%87%8D%E4%B8%8E%E6%A0%BC%E5%AD%90%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20EX%0A%20%20EX%20--%3E%20A%5B%22%E9%85%8D%E7%BD%AE%3A%20%E6%9D%83%E9%87%8D%E5%B7%AE%20%C3%97%20%E5%9F%BA%E5%87%86%E6%A0%BC%E5%AD%90%E6%94%B6%E7%9B%8A%22%5D%0A%20%20EX%20--%3E%20S%5B%22%E9%80%89%E6%8B%A9%3A%20%E5%9F%BA%E5%87%86%E6%9D%83%E9%87%8D%20%C3%97%20%E5%86%85%E9%83%A8%E8%B6%85%E9%A2%9D%22%5D%0A%20%20EX%20--%3E%20I%5B%22%E4%BA%A4%E4%BA%92%3A%20%E4%B8%A4%E9%A1%B9%E4%B9%8B%E7%A7%AF%22%5D%0A%20%20A%20--%3E%20LNK%5B%22%E5%A4%9A%E6%9C%9F%E8%BF%9E%E6%8E%A5%20Carino%20%2F%20Menchero%22%5D%0A%20%20S%20--%3E%20LNK%0A%20%20I%20--%3E%20LNK%0A%20%20LNK%20--%3E%20REP%5B%22%E5%8F%AF%E5%8A%A0%E6%80%BB%E7%9A%84%E7%BB%A9%E6%95%88%E6%8A%A5%E5%91%8A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Brinson–Hood–Beebower（1986）把单期超额拆成配置、选择与交互，会计上可加，依赖期初互斥分类。</li><li>Brinson–Fachler（1985）用格子相对总基准的超额做配置，避免「全上涨市里超配大行业恒为正」。</li><li>多期必须用连接算法，不能把单期三项直接相加；日频再连接比月平均权重更忠实于交易路径。</li><li>Brinson 是分区会计，不是因子模型；风格暴露与残差 alpha 应交给因子归因。</li><li>1986 年关于政策配置解释收益方差的表，不能翻译成「主动选择无价值」。</li><li>出处：Brinson, Hood and Beebower, <em>Determinants of Portfolio Performance</em>, Financial Analysts Journal, 1986；Brinson and Fachler, <em>Journal of Portfolio Management</em>, 1985；Carino, <em>Combining Attribution Effects Over Time</em>, Journal of Performance Measurement, 1999。</li></ul>',2))])}const q=o(h,[["render",_]]);export{f as __pageData,q as default};
